/**
 * L1 Automated Triage — Health Check Canary.
 *
 * CloudWatch Synthetics canary that performs outside-in API health checks
 * against every configured target URL on a schedule. It:
 *
 *   1. Retrieves auth credentials from Secrets Manager before any checks.
 *      If retrieval fails, it reports a credential-failure status and skips
 *      ALL health-check HTTP requests (Requirement 1.3).
 *   2. For each target URL, executes an HTTP GET with a 30s timeout and
 *      classifies the outcome: 2xx = SUCCESS, non-2xx = FAILED, no response
 *      within 30s = TIMEOUT (Requirements 1.4, 1.5, 1.6).
 *   3. Emits a structured JSON log entry per URL containing url, statusCode,
 *      responseBody, latencyMs, and timestamp (Requirement 1.7).
 *
 * The canary reports overall success/failure to CloudWatch Synthetics, which
 * feeds the `SuccessPercent` metric that the l1t-health- availability alarm
 * evaluates.
 *
 * Configuration is provided via environment variables set by the
 * L1HealthCanary CDK construct:
 *   - L1T_TARGET_URLS            comma-separated list of URLs, OR
 *   - L1T_TARGET_URLS_PARAMETER_NAME  SSM parameter holding the URL list
 *   - L1T_CREDENTIALS_SECRET_ARN Secrets Manager ARN for auth credentials
 *   - L1T_REQUEST_TIMEOUT_MS     per-request timeout (default 30000)
 */

'use strict';

const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');
const https = require('node:https');
const http = require('node:http');
const { URL } = require('node:url');

const { STATUS, formatLogEntry, MAX_RESPONSE_BODY_CHARS } = require('log-entry');

const DEFAULT_TIMEOUT_MS = 30000;

/**
 * Resolve the list of target URLs from configuration.
 *
 * Prefers the inline L1T_TARGET_URLS list; falls back to an SSM parameter
 * named by L1T_TARGET_URLS_PARAMETER_NAME.
 *
 * @returns {Promise<string[]>}
 */
async function resolveTargetUrls() {
    const inline = process.env.L1T_TARGET_URLS;
    if (inline && inline.trim().length > 0) {
        return inline
            .split(',')
            .map((u) => u.trim())
            .filter((u) => u.length > 0);
    }

    const parameterName = process.env.L1T_TARGET_URLS_PARAMETER_NAME;
    if (parameterName && parameterName.trim().length > 0) {
        const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssm');
        const ssm = new SSMClient({});
        const result = await ssm.send(new GetParameterCommand({ Name: parameterName, WithDecryption: false }));
        const value = result.Parameter && result.Parameter.Value ? result.Parameter.Value : '';
        return value
            .split(',')
            .map((u) => u.trim())
            .filter((u) => u.length > 0);
    }

    return [];
}

/**
 * Retrieve auth credentials from Secrets Manager.
 *
 * @param {string} secretArn Secrets Manager secret ARN
 * @returns {Promise<object|null>} parsed secret, or a raw string wrapper
 * @throws when the secret cannot be retrieved
 */
async function retrieveCredentials(secretArn) {
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
    const client = new SecretsManagerClient({});
    const response = await client.send(new GetSecretValueCommand({ SecretId: secretArn }));
    const raw = response.SecretString || '';
    try {
        return JSON.parse(raw);
    } catch (e) {
        // Secret is not JSON; return it as an opaque token.
        return { token: raw };
    }
}

/**
 * Build request headers from credentials.
 *
 * Supports a few common shapes without prescribing one:
 *   - { headerName, headerValue }  -> arbitrary header
 *   - { apiKey }                   -> x-api-key
 *   - { token } / string           -> Authorization: Bearer <token>
 *
 * @param {object|null} credentials
 * @returns {object} header map
 */
function buildAuthHeaders(credentials) {
    if (!credentials) {
        return {};
    }
    if (credentials.headerName && credentials.headerValue) {
        return { [credentials.headerName]: credentials.headerValue };
    }
    if (credentials.apiKey) {
        return { 'x-api-key': credentials.apiKey };
    }
    if (credentials.token) {
        return { Authorization: `Bearer ${credentials.token}` };
    }
    return {};
}

/**
 * Execute a single HTTP GET and classify the outcome.
 *
 * Resolves (never rejects) with a normalized health-check log entry so the
 * caller can process every URL regardless of individual failures.
 *
 * @param {string} targetUrl
 * @param {object} headers
 * @param {number} timeoutMs
 * @returns {Promise<object>} normalized log entry
 */
function checkUrl(targetUrl, headers, timeoutMs) {
    return new Promise((resolve) => {
        const startedAt = Date.now();
        let parsed;
        try {
            parsed = new URL(targetUrl);
        } catch (e) {
            resolve(
                formatLogEntry({
                    url: targetUrl,
                    status: STATUS.FAILED,
                    responseBody: `Invalid URL: ${e.message}`,
                    latencyMs: 0,
                }),
            );
            return;
        }

        const client = parsed.protocol === 'https:' ? https : http;
        const options = {
            method: 'GET',
            hostname: parsed.hostname,
            port: parsed.port || (parsed.protocol === 'https:' ? 443 : 80),
            path: `${parsed.pathname}${parsed.search}`,
            headers,
            timeout: timeoutMs,
        };

        const request = client.request(options, (res) => {
            let body = '';
            res.on('data', (chunk) => {
                if (body.length < MAX_RESPONSE_BODY_CHARS) {
                    body += chunk.toString();
                }
            });
            res.on('end', () => {
                const latencyMs = Date.now() - startedAt;
                resolve(
                    formatLogEntry({
                        url: targetUrl,
                        statusCode: res.statusCode,
                        responseBody: body,
                        latencyMs,
                    }),
                );
            });
        });

        request.on('timeout', () => {
            const latencyMs = Date.now() - startedAt;
            request.destroy();
            resolve(
                formatLogEntry({
                    url: targetUrl,
                    status: STATUS.TIMEOUT,
                    responseBody: null,
                    latencyMs,
                }),
            );
        });

        request.on('error', (error) => {
            const latencyMs = Date.now() - startedAt;
            // A destroyed-on-timeout socket also emits 'error'; the timeout
            // handler has already resolved, so this resolve is a no-op then.
            resolve(
                formatLogEntry({
                    url: targetUrl,
                    status: STATUS.FAILED,
                    responseBody: `Request error: ${error.message}`,
                    latencyMs,
                }),
            );
        });

        request.end();
    });
}

/**
 * Main canary body: resolve config, retrieve credentials, run checks.
 *
 * @returns {Promise<void>}
 * @throws when credentials fail or any URL check does not succeed, so the
 *   canary run is marked failed and the SuccessPercent metric drops.
 */
const runHealthChecks = async function () {
    const timeoutMs = Number(process.env.L1T_REQUEST_TIMEOUT_MS) || DEFAULT_TIMEOUT_MS;
    const credentialsSecretArn = process.env.L1T_CREDENTIALS_SECRET_ARN;

    const targetUrls = await resolveTargetUrls();
    if (targetUrls.length === 0) {
        log.error('No target URLs configured (set L1T_TARGET_URLS or L1T_TARGET_URLS_PARAMETER_NAME)');
        throw new Error('No target URLs configured');
    }

    // Step 1: retrieve credentials BEFORE any health-check requests.
    // On failure, report a credential-failure status and skip all checks.
    let credentials = null;
    if (credentialsSecretArn && credentialsSecretArn.trim().length > 0) {
        try {
            credentials = await retrieveCredentials(credentialsSecretArn);
            log.info('Successfully retrieved canary credentials from Secrets Manager');
        } catch (error) {
            const entry = formatLogEntry({
                url: 'N/A',
                status: STATUS.CREDENTIAL_FAILURE,
                responseBody: `Credential retrieval failed: ${error.message}`,
                latencyMs: 0,
            });
            log.error(JSON.stringify(entry));
            throw new Error(`Credential retrieval failed; skipping all health checks: ${error.message}`);
        }
    } else {
        log.info('No credentials secret configured; proceeding with unauthenticated health checks');
    }

    const headers = buildAuthHeaders(credentials);

    // Step 2 & 3: check every URL, log a structured entry per URL.
    let anyFailure = false;
    for (const targetUrl of targetUrls) {
        const entry = await synthetics.executeStep(`healthcheck_${sanitizeStepName(targetUrl)}`, async function () {
            const result = await checkUrl(targetUrl, headers, timeoutMs);
            // Structured JSON per URL to /aws/synthetics/{canary-name}.
            log.info(JSON.stringify(result));
            return result;
        });

        if (entry.status !== STATUS.SUCCESS) {
            anyFailure = true;
        }
    }

    if (anyFailure) {
        throw new Error('One or more health checks did not return a 2xx status');
    }
};

/**
 * Produce a Synthetics-safe step name fragment from a URL.
 *
 * @param {string} targetUrl
 * @returns {string}
 */
function sanitizeStepName(targetUrl) {
    return targetUrl.replace(/[^a-zA-Z0-9]/g, '_').slice(0, 60);
}

exports.handler = async () => {
    return await runHealthChecks();
};

// Exported for unit testing (ignored by the Synthetics runtime).
exports.__test__ = {
    resolveTargetUrls,
    buildAuthHeaders,
    checkUrl,
    sanitizeStepName,
};
